import { cp, mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const generatedMarker =
  "<!-- GENERATED BY kiel-sealevel-cms contracts:sync -->";
const generatedReadme = `${generatedMarker}

# Generated API contracts

Do not edit this directory. Its source is
\`kiel-sealevel-cms/packages/api-contracts/src\`.

Regenerate it from the CMS repository with \`pnpm contracts:sync\`.
From the frontend repository, run
\`pnpm --dir ../kiel-sealevel-cms contracts:sync\`.

Commit this generated directory with the frontend for independent deployments.
`;

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const cmsRoot = path.resolve(scriptDirectory, "..");
const sourceDirectory = path.join(cmsRoot, "packages/api-contracts/src");
const frontendRoot = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.resolve(cmsRoot, "../kiel-sealevel-frontend");
const frontendSourceDirectory = path.join(frontendRoot, "src");
const targetDirectory = path.join(frontendSourceDirectory, "api-contracts");

async function readDirectory(directory, optional = false) {
  try {
    return await readdir(directory);
  } catch (error) {
    if (optional && error?.code === "ENOENT") {
      return null;
    }

    throw error;
  }
}

async function validateTarget() {
  const readme = await readFile(
    path.join(targetDirectory, "README.md"),
    "utf8",
  ).catch((error) => {
    if (error?.code === "ENOENT") {
      return "";
    }

    throw error;
  });
  if (!readme.startsWith(generatedMarker)) {
    throw new Error(
      `Refusing to replace unmarked directory: ${targetDirectory}`,
    );
  }
}

await readDirectory(sourceDirectory);
await readDirectory(frontendSourceDirectory);
const targetEntries = (await readDirectory(targetDirectory, true)) ?? [];
if (targetEntries.length > 0) {
  await validateTarget();
}

await mkdir(targetDirectory, { recursive: true });

for (const entry of targetEntries) {
  await rm(path.join(targetDirectory, entry), { recursive: true, force: true });
}

await cp(sourceDirectory, targetDirectory, { recursive: true });
await writeFile(path.join(targetDirectory, "README.md"), generatedReadme);

console.log(`Synced API contracts to ${targetDirectory}`);
